insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('jer-2-35','jer','예레미야',2,35,'그러나 너는 말하기를 나는 무죄하니 그의 진노가 참으로 내게서 떠났다 하거니와 보라 네 말이 나는 죄를 범하지 아니하였다 하였으므로 내가 너를 심판하리라',19001),
('jer-2-36','jer','예레미야',2,36,'네가 어찌하여 네 길을 바꾸어 부지런히 돌아다니느냐 네가 앗수르로 말미암아 수치를 당함 같이 또한 애굽으로 말미암아 수치를 당할 것이라',19002),
('jer-2-37','jer','예레미야',2,37,'네가 두 손으로 네 머리를 싸고 거기서도 나가리니 이는 네가 의지하는 자들을 나 여호와가 버렸으므로 네가 그들로 말미암아 형통하지 못할 것임이라',19003),
('jer-3-1','jer','예레미야',3,1,'그들이 말하기를 가령 사람이 그의 아내를 버리므로 그가 그에게서 떠나 타인의 아내가 된다 하자 남편이 그를 다시 받겠느냐 그리하면 그 땅이 크게 더러워지지 아니하겠느냐 하느니라 네가 많은 무리와 행음하고서도 내게로 돌아오려느냐 여호와의 말씀이니라',19004),
('jer-3-2','jer','예레미야',3,2,'네 눈을 들어 헐벗은 산을 보라 네가 행음하지 아니한 곳이 어디 있느냐 네가 길 가에 앉아 사람들을 기다린 것이 광야에 있는 아라바 사람 같아서 음란과 행악으로 이 땅을 더럽혔도다',19005),
('jer-3-3','jer','예레미야',3,3,'그러므로 단비가 그쳤고 늦은 비가 없어졌느니라 그럴지라도 네가 창녀의 낯을 가졌으므로 수치를 알지 못하느니라',19006),
('jer-3-4','jer','예레미야',3,4,'네가 이제부터는 내게 부르짖기를 나의 아버지여 아버지는 나의 청년 시절의 보호자이시오니',19007),
('jer-3-5','jer','예레미야',3,5,'노여움을 한없이 계속하시겠으며 끝까지 품으시겠나이까 하지 아니하겠느냐 보라 네가 이같이 말하여도 악을 행하여 네 욕심을 이루었느니라 하시니라',19008),
('jer-3-6','jer','예레미야',3,6,'요시야 왕 때에 여호와께서 또 내게 이르시되 너는 배역한 이스라엘이 행한 바를 보았느냐 그가 모든 높은 산에 오르며 모든 푸른 나무 아래로 가서 거기서 행음하였도다',19009),
('jer-3-7','jer','예레미야',3,7,'그가 이 모든 일들을 행한 후에 내가 말하기를 그가 내게로 돌아오리라 하였으나 아직도 내게로 돌아오지 아니하였고 그의 반역한 자매 유다는 그것을 보았느니라',19010),
('jer-3-8','jer','예레미야',3,8,'내게 배역한 이스라엘이 간음을 행하였으므로 내가 그를 내쫓고 그에게 이혼서까지 주었으되 그의 반역한 자매 유다가 두려워하지 아니하고 자기도 가서 행음함을 내가 보았노라',19011),
('jer-3-9','jer','예레미야',3,9,'그가 돌과 나무와 더불어 행음함을 가볍게 여기고 행음하여 이 땅을 더럽혔거늘',19012),
('jer-3-10','jer','예레미야',3,10,'이 모든 일이 있어도 그의 반역한 자매 유다가 진심으로 내게 돌아오지 아니하고 거짓으로 할 뿐이니라 여호와의 말씀이니라',19013),
('jer-3-11','jer','예레미야',3,11,'여호와께서 내게 이르시되 배역한 이스라엘은 반역한 유다보다 자신이 더 의로움이 나타났나니',19014),
('jer-3-12','jer','예레미야',3,12,'너는 가서 북을 향하여 이 말을 선포하여 이르라 여호와께서 이르시되 배역한 이스라엘아 돌아오라 나의 노한 얼굴을 너희에게로 향하지 아니하리라 나는 긍휼이 있는 자라 노를 한없이 품지 아니하느니라 여호와의 말씀이니라',19015),
('jer-3-13','jer','예레미야',3,13,'너는 오직 네 죄를 자복하라 이는 네 하나님 여호와를 배반하고 네 길로 달려 이방인들에게로 나아가 모든 푸른 나무 아래로 가서 내 목소리를 듣지 아니하였음이라 여호와의 말씀이니라',19016),
('jer-3-14','jer','예레미야',3,14,'여호와의 말씀이니라 배역한 자식들아 돌아오라 나는 너희 남편임이라 내가 너희를 성읍에서 하나와 족속 중에서 둘을 택하여 너희를 시온으로 데려오겠고',19017),
('jer-3-15','jer','예레미야',3,15,'내가 또 내 마음에 합한 목자들을 너희에게 주리니 그들이 지식과 명철로 너희를 양육하리라',19018),
('jer-3-16','jer','예레미야',3,16,'여호와의 말씀이니라 너희가 이 땅에서 번성하여 많아질 때에는 사람들이 여호와의 언약궤를 다시는 말하지 아니할 것이요 생각하지 아니할 것이요 기억하지 아니할 것이요 찾지 아니할 것이요 다시는 만들지 아니할 것이며',19019),
('jer-3-17','jer','예레미야',3,17,'그 때에 예루살렘이 그들에게 여호와의 보좌라 일컬음이 되며 모든 백성이 그리로 모이리니 곧 여호와의 이름으로 말미암아 예루살렘에 모이고 다시는 그들의 악한 마음의 완악한 대로 그들이 행하지 아니할 것이며',19020),
('jer-3-18','jer','예레미야',3,18,'그 때에 유다 족속이 이스라엘 족속과 동행하여 북에서부터 나와서 내가 너희 조상들에게 기업으로 준 땅에 그들이 함께 이르리라',19021),
('jer-3-19','jer','예레미야',3,19,'내가 말하기를 내가 어떻게 하든지 너를 자녀들 중에 두며 허다한 나라들 중에 아름다운 기업인 이 귀한 땅을 네게 주리라 하였고 내가 다시 말하기를 너희가 나를 나의 아버지라 하고 나를 떠나지 말 것이니라 하였노라',19022),
('jer-3-20','jer','예레미야',3,20,'그런데 이스라엘 족속아 마치 아내가 그의 남편을 속이고 떠나감 같이 너희가 확실히 나를 속였느니라 여호와의 말씀이니라',19023),
('jer-3-21','jer','예레미야',3,21,'소리가 헐벗은 산 위에서 들리니 곧 이스라엘 자손이 애곡하며 간구하는 것이라 그들이 그들의 길을 굽게 하며 자기 하나님 여호와를 잊어버렸음이로다',19024),
('jer-3-22','jer','예레미야',3,22,'배역한 자식들아 돌아오라 내가 너희의 배역함을 고치리라 하시니라. 보소서  우리가 주께 왔사오니 주는 우리 하나님 여호와이심이니이다',19025),
('jer-3-23','jer','예레미야',3,23,'작은 산들과 큰 산 위에서 떠드는 것은 참으로 헛된 일이라 이스라엘의 구원은 진실로 우리 하나님 여호와께 있나이다',19026),
('jer-3-24','jer','예레미야',3,24,'부끄러운 그것이 우리가 청년의 때로부터 우리 조상들의 산업인 양 떼와 소 떼와 아들들과 딸들을 삼켰사온즉',19027),
('jer-3-25','jer','예레미야',3,25,'우리는 수치 중에 눕겠고 우리의 치욕이 우리를 덮을 것이니 이는 우리와 우리 조상들이 청년의 때로부터 오늘까지 우리 하나님 여호와께 범죄하여 우리 하나님 여호와의 목소리에 순종하지 아니하였음이니이다',19028),
('jer-4-1','jer','예레미야',4,1,'여호와께서 이르시되 이스라엘아 네가 돌아오려거든 내게로 돌아오라 네가 만일 나의 목전에서 가증한 것을 버리고 네가 흔들리지 아니하며',19029),
('jer-4-2','jer','예레미야',4,2,'진실과 정의와 공의로 여호와의 삶을 두고 맹세하면 나라들이 나로 말미암아 스스로 복을 빌며 나로 말미암아 자랑하리라',19030),
('jer-4-3','jer','예레미야',4,3,'여호와께서 유다와 예루살렘 사람에게 이와 같이 이르노라 너희 묵은 땅을 갈고 가시덤불에 파종하지 말라',19031),
('jer-4-4','jer','예레미야',4,4,'유다인과 예루살렘 주민들아 너희는 스스로 할례를 행하여 너희 마음 가죽을 베고 나 여호와께 속하라 그리하지 아니하면 너희 악행으로 말미암아 나의 분노가 불 같이 일어나 사르리니 그것을 끌 자가 없으리라',19032),
('jer-4-5','jer','예레미야',4,5,'너희는 유다에 선포하며 예루살렘에 공포하여 이르기를 이 땅에서 나팔을 불라 하며 또 크게 외쳐 이르기를 너희는 모이라 우리가 견고한 성으로 들어가자 하고',19033),
('jer-4-6','jer','예레미야',4,6,'시온을 향하여 깃발을 세우라, 도피하라, 지체하지 말라, 내가 북방에서 재난과 큰 멸망을 가져오리라',19034),
('jer-4-7','jer','예레미야',4,7,'사자가 그 수풀에서 올라왔으며 나라들을 멸하는 자가 나아 왔으되 네 땅을 황폐하게 하려고 이미 그의 처소를 떠났은즉 네 성읍들이 황폐하여 주민이 없게 되리니',19035),
('jer-4-8','jer','예레미야',4,8,'이로 말미암아 너희는 굵은 베를 두르고 애곡하라 이는 여호와의 맹렬한 노가 아직 너희에게서 돌이키지 아니하였음이라',19036),
('jer-4-9','jer','예레미야',4,9,'여호와의 말씀이니라 그 날에 왕과 지도자들은 낙심할 것이며 제사장들은 놀랄 것이며 선지자들은 깜짝 놀라리라',19037),
('jer-4-10','jer','예레미야',4,10,'내가 이르되 슬프도소이다 주 여호와여 주께서 진실로 이 백성과 예루살렘을 크게 속이셨나이다 이르시기를 너희에게 평강이 있으리라 하시더니 칼이 생명에 이르렀나이다',19038),
('jer-4-11','jer','예레미야',4,11,'그 때에 이 백성과 예루살렘에 전할 자가 있어서 뜨거운 바람이 광야에 있는 헐벗은 산에서 내 딸 백성에게 불어온다 하리라 이는 키질하기 위함도 아니요 정결하게 하려 함도 아니며',19039),
('jer-4-12','jer','예레미야',4,12,'이보다 더 강한 바람이 나를 위하여 오리니 이제 내가 그들에게 심판을 행할 것이라',19040),
('jer-4-13','jer','예레미야',4,13,'보라 그가 구름 같이 올라오나니 그의 병거는 회오리바람 같고 그의 말들은 독수리보다 빠르도다 우리에게 화 있도다 우리는 멸망하도다 하리라',19041),
('jer-4-14','jer','예레미야',4,14,'예루살렘아 네 마음의 악을 씻어 버리라 그리하면 구원을 얻으리라 네 악한 생각이 네 속에 얼마나 오래 머물겠느냐',19042),
('jer-4-15','jer','예레미야',4,15,'단에서 소리를 선포하며 에브라임 산에서 재앙을 공포하는도다',19043),
('jer-4-16','jer','예레미야',4,16,'너희는 여러 나라에 전하며 또 예루살렘에 알리기를 에워싸고 치는 자들이 먼 땅에서부터 와서 유다 성읍들을 향하여 소리를 지른다 하라',19044),
('jer-4-17','jer','예레미야',4,17,'그들이 밭을 지키는 자 같이 예루살렘을 에워싸나니 이는 그가 나를 거역했기 때문이니라 여호와의 말씀이니라',19045),
('jer-4-18','jer','예레미야',4,18,'네 길과 행위가 이 일들을 부르게 하였나니 이는 네가 악함이라 그 고통이 네 마음에까지 미치느니라',19046),
('jer-4-19','jer','예레미야',4,19,'슬프고 아프다 내 마음속이 아프고 내 마음이 답답하여 잠잠할 수 없으니 이는 나의 심령이 나팔 소리와 전쟁의 경보를 들음이로다',19047),
('jer-4-20','jer','예레미야',4,20,'패망에 패망이 연속하여 온 땅이 탈취를 당하니 나의 장막과 휘장은 갑자기 파멸되도다',19048),
('jer-4-21','jer','예레미야',4,21,'내가 저 깃발을 보며 나팔 소리 듣기를 어느 때까지 할꼬',19049),
('jer-4-22','jer','예레미야',4,22,'내 백성은 나를 알지 못하는 어리석은 자요 지각이 없는 미련한 자식이라 악을 행하기에는 지각이 있으나 선을 행하기에는 무지하도다',19050),
('jer-4-23','jer','예레미야',4,23,'보라 내가 땅을 본즉 혼돈하고 공허하며 하늘에는 빛이 없으며',19051),
('jer-4-24','jer','예레미야',4,24,'내가 산들을 본즉 다 진동하며 작은 산들도 요동하며',19052),
('jer-4-25','jer','예레미야',4,25,'내가 본즉 사람이 없으며 공중의 새가 다 날아갔으며',19053),
('jer-4-26','jer','예레미야',4,26,'보라 내가 본즉 좋은 땅이 황무지가 되었으며 그 모든 성읍이 여호와의 앞 그의 맹렬한 진노 앞에 무너졌으니',19054),
('jer-4-27','jer','예레미야',4,27,'여호와께서 이와 같이 말씀하시길 이 온 땅이 황폐할 것이나 내가 진멸하지는 아니할 것이며',19055),
('jer-4-28','jer','예레미야',4,28,'이로 말미암아 땅이 슬퍼할 것이며 위의 하늘이 어두울 것이라 내가 이미 말하였으며 작정하였고 후회하지 아니하였은즉 또한 거기서 돌이키지 아니하리라 하셨음이로다',19056),
('jer-4-29','jer','예레미야',4,29,'기병과 활 쏘는 자의 함성으로 말미암아 모든 성읍 사람들이 도망하여 수풀에 들어가고 바위에 기어오르며 각 성읍이 버림을 당하여 거기 사는 사람이 없나니',19057),
('jer-4-30','jer','예레미야',4,30,'멸망을 당한 자여 네가 어떻게 하려느냐 네가 붉은 옷을 입고 금장식으로 단장하고 눈을 그려 꾸밀지라도 네가 화장한 것이 헛된 일이라 연인들이 너를 멸시하여 네 생명을 찾느니라',19058),
('jer-4-31','jer','예레미야',4,31,'내가 소리를 들은즉 여인의 해산하는 소리 같고 초산하는 자의 고통하는 소리 같으니 이는 시온의 딸의 소리라 그가 헐떡이며 그의 손을 펴고 이르기를 내게 화가 있도다 죽이는 자로 말미암아 나의 심령이 피곤하도다 하는도다',19059),
('jer-5-1','jer','예레미야',5,1,'너희는 예루살렘 거리로 빨리 다니며 그 넓은 거리에서 찾아보고 알라 너희가 만일 정의를 행하며 진리를 구하는 자를 한 사람이라도 찾으면 내가 이 성읍을 용서하리라',19060),
('jer-5-2','jer','예레미야',5,2,'그들이 여호와께서 살아 계심을 두고 맹세할지라도 실상은 거짓 맹세니라',19061),
('jer-5-3','jer','예레미야',5,3,'여호와여 주의 눈이 진리를 찾지 아니하시나이까 주께서 그들을 치셨을지라도 그들이 아픈 줄을 알지 못하며 그들을 멸하셨을지라도 그들이 징계를 받지 아니하고 그들의 얼굴을 바위보다 굳게 하여 돌아오기를 싫어하므로',19062),
('jer-5-4','jer','예레미야',5,4,'내가 말하기를 이 무리는 비천하고 어리석은 것뿐이라 여호와의 길, 자기 하나님의 법을 알지 못하니',19063),
('jer-5-5','jer','예레미야',5,5,'내가 지도자들에게 가서 그들에게 말하리라 그들은 여호와의 길, 자기 하나님의 법을 안다 하였더니 그들도 일제히 멍에를 꺾고 결박을 끊은지라',19064),
('jer-5-6','jer','예레미야',5,6,'그러므로 수풀에서 나오는 사자가 그들을 죽이며 사막의 이리가 그들을 멸하며 표범이 성읍들을 엿본즉 그리로 나오는 자마다 찢기리니 이는 그들의 허물이 많고 반역이 심함이니이다',19065),
('jer-5-7','jer','예레미야',5,7,'내가 어찌 너를 용서하겠느냐 네 자녀가 나를 버리고 신이 아닌 것들로 맹세하였으며 내가 그들을 배불리 먹인즉 그들이 간음하며 창기의 집에 허다히 모이며',19066),
('jer-5-8','jer','예레미야',5,8,'그들은 두루 다니는 살진 수말 같이 각기 이웃의 아내를 따르며 소리지르는도다',19067),
('jer-5-9','jer','예레미야',5,9,'여호와의 말씀이니라 내가 어찌 이 일들에 대하여 벌하지 아니하겠으며 내 마음이 이런 나라에 보복하지 않겠느냐',19068),
('jer-5-10','jer','예레미야',5,10,'너희는 그 성벽에 올라가 무너뜨리되 다 무너뜨리지 말고 그 가지만 꺾어 버리라 여호와의 것이 아님이니라',19069),
('jer-5-11','jer','예레미야',5,11,'여호와의 말씀이니라 이스라엘의 집과 유다의 집이 내게 심히 반역하였느니라',19070),
('jer-5-12','jer','예레미야',5,12,'그들이 여호와를 인정하지 아니하며 말하기를 여호와께서는 계시지 아니하니 재앙이 우리에게 임하지 아니할 것이요 우리가 칼과 기근을 보지 아니할 것이며',19071),
('jer-5-13','jer','예레미야',5,13,'선지자들은 바람이라 말씀이 그들의 속에 있지 아니한즉 그같이 그들이 당하리라 하느니라',19072),
('jer-5-14','jer','예레미야',5,14,'그러므로 만군의 하나님 여호와께서 이와 같이 말씀하시니라 너희가 이 말을 하였은즉 볼지어다 내가 네 입에 있는 나의 말을 불이 되게 하고 이 백성을 나무가 되게 하여 불사르리라',19073),
('jer-5-15','jer','예레미야',5,15,'여호와의 말씀이니라 이스라엘 집이여 보라 내가 한 나라를 먼 곳에서 너희에게로 오게 하리니 곧 강하고 오랜 민족이라 그 나라 말을 네가 알지 못하며 그 말을 네가 깨닫지 못하느니라',19074),
('jer-5-16','jer','예레미야',5,16,'그 화살통은 열린 무덤이요 그 사람들은 다 용사라',19075),
('jer-5-17','jer','예레미야',5,17,'그들이 네 자녀들이 먹을 추수 곡물과 양식을 먹으며 네 양 떼와 소 떼를 먹으며 네 포도나무와 무화과나무 열매를 먹으며 네가 믿는 견고한 성들을 칼로 파멸하리라',19076),
('jer-5-18','jer','예레미야',5,18,'여호와의 말씀이니라 그 때에도 내가 너희를 진멸하지는 아니하리라',19077),
('jer-5-19','jer','예레미야',5,19,'그들이 만일 이르기를 우리 하나님 여호와께서 어찌하여 이 모든 일을 우리에게 행하셨느냐 하거든 너는 그들에게 이르기를 너희가 여호와를 버리고 너희 땅에서 이방 신들을 섬겼은즉 이와 같이 너희 것이 아닌 땅에서 이방인들을 섬기리라 하라',19078),
('jer-5-20','jer','예레미야',5,20,'너는 이를 야곱 집에 선포하며 유다에 공포하여 이르기를',19079),
('jer-5-21','jer','예레미야',5,21,'어리석고 지각이 없으며 눈이 있어도 보지 못하며 귀가 있어도 듣지 못하는 백성이여 이를 들을지어다',19080),
('jer-5-22','jer','예레미야',5,22,'여호와의 말씀이니라 너희가 나를 두려워하지 아니하느냐 내 앞에서 떨지 아니하겠느냐 내가 모래를 두어 바다의 한계를 삼되 그것으로 영원한 한계를 삼고 지나치지 못하게 하였으므로 파도가 거세게 이나 그것을 이기지 못하며 뛰노나 그것을 넘지 못하느니라',19081),
('jer-5-23','jer','예레미야',5,23,'그러나 너희 백성은 배반하며 반역하는 마음이 있어서 이미 배반하고 갔으며',19082),
('jer-5-24','jer','예레미야',5,24,'또 너희 마음으로 우리에게 이른 비와 늦은 비를 때를 따라 주시며 우리를 위하여 추수 기한을 정하시는 우리 하나님 여호와를 경외하자 말하지도 아니하니',19083),
('jer-5-25','jer','예레미야',5,25,'너희 허물이 이러한 일들을 물리쳤고 너희 죄가 너희로부터 좋은 것을 막았느니라',19084),
('jer-5-26','jer','예레미야',5,26,'내 백성 가운데 악인이 있어서 새 사냥꾼이 매복함 같이 지키며 덫을 놓아 사람을 잡으며',19085),
('jer-5-27','jer','예레미야',5,27,'새장에 새들이 가득함 같이 너희 집들에 속임이 가득하도다 그러므로 너희가 번창하고 거부가 되어',19086),
